package vn.codex.garenapopup;
import android.app.Activity;import android.app.AlertDialog;import android.content.Intent;import android.net.Uri;import android.os.Build;import android.widget.TextView;import org.json.*;import java.net.*;import java.io.*;import java.util.concurrent.*;
final class GithubUpdateChecker {
 // Set this to the GitHub repository that publishes the APK in Releases.
 private static final String OWNER="hack10293u-blip",REPO="autologgrn";
 private static final ExecutorService EXEC=Executors.newSingleThreadExecutor();
 static void check(Activity a,TextView status){if(OWNER.startsWith("YOUR_")||REPO.startsWith("YOUR_")){status.setText("Cần cấu hình repository GitHub Releases trước.");return;}status.setText("Đang kiểm tra cập nhật...");EXEC.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL("https://api.github.com/repos/"+OWNER+"/"+REPO+"/releases/latest").openConnection();c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("User-Agent","AutoLoginGarena-Android");c.setConnectTimeout(10000);c.setReadTimeout(10000);int response=c.getResponseCode();if(response==404)throw new IOException("Repo chưa có GitHub Release công khai. Hãy phát hành Release kèm APK trước.");if(response!=200)throw new IOException("HTTP "+response);StringBuilder body=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream(),"UTF-8"))){String line;while((line=r.readLine())!=null)body.append(line);}JSONObject release=new JSONObject(body.toString());String tag=extractVersion(release.optString("name",""),release.optString("tag_name",""));if(tag.isEmpty())throw new IOException("Không đọc được số phiên bản trong Release.");JSONArray assets=release.optJSONArray("assets");String apk=null;if(assets!=null)for(int i=0;i<assets.length();i++){JSONObject item=assets.getJSONObject(i);if(item.optString("name").toLowerCase().endsWith(".apk")){apk=item.optString("browser_download_url");break;}}String link=apk==null?release.optString("html_url",""):apk;String current=BuildConfig.VERSION_NAME;if(tag.isEmpty()||link.isEmpty())throw new IOException("Release/APK chưa có");if(compare(tag,current)<=0){a.runOnUiThread(()->status.setText("Bạn đang dùng bản mới nhất ("+current+")."));return;}String finalLink=link;a.runOnUiThread(()->new AlertDialog.Builder(a).setTitle("Có bản mới "+tag).setMessage("Bản hiện tại: "+current+". Mở trang tải APK? Android sẽ yêu cầu xác nhận cài đặt.").setNegativeButton("Để sau",(d,w)->{}).setPositiveButton("Tải APK",(d,w)->{try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(finalLink)));}catch(Exception e){status.setText("Không mở được liên kết tải APK.");}}).show());}catch(Exception e){a.runOnUiThread(()->status.setText("Không kiểm tra được cập nhật: "+e.getMessage()));}});}
 private static String extractVersion(String name,String tag){java.util.regex.Pattern p=java.util.regex.Pattern.compile("(?i)(?<![0-9])v?[0-9]+(?:\\.[0-9]+){1,3}");for(String value:new String[]{name,tag}){java.util.regex.Matcher m=p.matcher(value==null?"":value);if(m.find())return m.group().replaceFirst("(?i)^v","");}return "";}
 private static int compare(String x,String y){String[] a=x.split("\\."),b=y.split("\\.");for(int i=0;i<Math.max(a.length,b.length);i++){int n=i<a.length?Integer.parseInt(a[i]):0,m=i<b.length?Integer.parseInt(b[i]):0;if(n!=m)return Integer.compare(n,m);}return 0;}
}